import { Injectable } from '@angular/core';
import { Meta, Title } from '@angular/platform-browser';

@Injectable({
    providedIn: 'root'
})
export class SeoService {

    constructor(private title: Title, private meta: Meta) { }

    updateMetaTags(config: { title?: string, description?: string, image?: string, url?: string }) {
        const defaultTitle = 'Anka - Trouvez votre futur chez-vous en quelques clics';
        const defaultDesc = 'Anka est votre plateforme de location immobilière simplifiée. Trouvez des villas, appartements et studios d’exception avec l’aide de notre IA.';
        const defaultImage = 'https://anka-app.com/assets/img/og-image.jpg';
        const defaultUrl = 'https://anka-app.com/';

        const finalTitle = config.title ? `${config.title} | Anka` : defaultTitle;
        const finalDesc = config.description || defaultDesc;
        const finalImage = config.image || defaultImage;
        const finalUrl = config.url || defaultUrl;

        // Standard Meta Tags
        this.title.setTitle(finalTitle);
        this.meta.updateTag({ name: 'description', content: finalDesc });

        // Open Graph / Facebook
        this.meta.updateTag({ property: 'og:title', content: finalTitle });
        this.meta.updateTag({ property: 'og:description', content: finalDesc });
        this.meta.updateTag({ property: 'og:image', content: finalImage });
        this.meta.updateTag({ property: 'og:url', content: finalUrl });

        // Twitter
        this.meta.updateTag({ name: 'twitter:title', content: finalTitle });
        this.meta.updateTag({ name: 'twitter:description', content: finalDesc });
        this.meta.updateTag({ name: 'twitter:image', content: finalImage });
    }

    resetMetaTags() {
        this.updateMetaTags({});
    }
}
