import { Component, Input, AfterViewInit, ElementRef, ViewChild, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule, DecimalPipe } from '@angular/common';
import { House } from '../../models/house.model';
import { RouterLink } from '@angular/router';

declare const bootstrap: any;

@Component({
  selector: 'app-house-item',
  standalone: true,
  imports: [CommonModule, RouterLink, DecimalPipe],
  templateUrl: './house-item.component.html',
  styleUrls: ['./house-item.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class HouseItemComponent implements AfterViewInit {
  @Input() house!: House;

  @ViewChild('carouselElem') carouselRef!: ElementRef;

  ngAfterViewInit() {
    if (this.carouselRef?.nativeElement) {
      new bootstrap.Carousel(this.carouselRef.nativeElement);
    }
  }
}
