import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { HttpClient, HttpParams } from "@angular/common/http";
import { Observable } from "rxjs";
import { environment } from "../../../environments/environment";


@Injectable({ providedIn: 'root' })
export class AnkaService {


  constructor(private http: HttpClient) { }
  apiUrl: string = environment.apiUrl;
  private _isOpen = new BehaviorSubject<boolean>(false);
  isOpen$ = this._isOpen.asObservable();
  ankaList: boolean = false;

  // Chat History
  private _messages: { text: string, type: 'user' | 'ai', timestamp: Date }[] = [];

  get messages() {
    return this._messages;
  }

  addMessage(text: string, type: 'user' | 'ai') {
    this._messages.push({ text, type, timestamp: new Date() });
  }

  clearHistory() {
    this._messages = [];
  }

  toggle() {
    console.log('Anka window toggled:', this._isOpen.value);
    this._isOpen.next(!this._isOpen.value);

  }

  open() {
    this._isOpen.next(true);
  }

  close() {
    this._isOpen.next(false);
  }


  ankaListToggle() {
    this.ankaList = !this.ankaList;
  }

  getAnkaListStatus(): boolean {
    return this.ankaList;
  }






  sendPrompt(message: string) {
    return this.http.post<any>(`http://127.0.0.1:3000/api/anka`, { message });
  }
}
