import { Component, OnInit } from '@angular/core';
import { AnkaService } from '../../service/anka.service';
import { Observable } from 'rxjs';
import { FormBuilder, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { AsyncPipe, NgIf, NgFor, NgClass } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'anka-window',
  imports: [ReactiveFormsModule, NgIf, AsyncPipe, NgFor, NgClass],
  templateUrl: './anka-window.component.html',
  styleUrls: ['./anka-window.component.scss']
})
export class AnkaWindowComponent implements OnInit {

  isOpen$!: Observable<boolean>
  form!: FormGroup

  loading: boolean = false;
  showResult: boolean = false;
  resultData: any = null;
  errorMessage: string | null = null;

  constructor(public anka: AnkaService, private fb: FormBuilder, private router: Router) {
    this.isOpen$ = this.anka.isOpen$;

    this.form = this.fb.group({
      message: ['']
    });
  }

  ngOnInit(): void {
    // No specific logic needed here as we read directly from service
  }

  close() { this.anka.close(); }

  send() {
    const message = this.form.get('message')?.value;
    if (!message) return;

    // Add user message to history
    this.anka.addMessage(message, 'user');

    this.loading = true;
    this.showResult = false;
    this.errorMessage = null;
    this.form.reset(); // Clear input immediately

    this.anka.sendPrompt(message).subscribe({
      next: (response) => {
        this.resultData = response;
        this.loading = false;
        this.showResult = true;

        this.router.navigate(['/ankaList'], {
          state: { data: response },
          queryParams: { reload: Date.now() }
        });

        this.close();
        this.form.reset();
        this.loading = false;
        this.showResult = false;
      },
      error: (err) => {
        console.error("Erreur Anka:", err);
        this.loading = false;
        this.errorMessage = "Désolé, une erreur est survenue lors de l'analyse de votre demande. Veuillez réessayer.";
      }
    });
  }
}
